CREATE TABLE jobs (id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, dedupe_key TEXT, payload TEXT NOT NULL, priority INTEGER NOT NULL DEFAULT 100, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, max_attempts INTEGER NOT NULL DEFAULT 3, last_error TEXT, run_after TEXT NOT NULL, locked_by TEXT, locked_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX idx_jobs_dedupe ON jobs(kind, dedupe_key) WHERE status='pending';
CREATE INDEX idx_jobs_claim ON jobs(status, priority, run_after);
CREATE TABLE translation_tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, article_id TEXT NOT NULL, source_locale TEXT NOT NULL, target_locale TEXT NOT NULL, source_revision INTEGER NOT NULL, status TEXT NOT NULL, job_id INTEGER REFERENCES jobs(id) ON DELETE SET NULL, segments_total INTEGER DEFAULT 0, segments_done INTEGER DEFAULT 0, tokens_in INTEGER DEFAULT 0, tokens_out INTEGER DEFAULT 0, provider TEXT, model TEXT, error TEXT, started_at TEXT, finished_at TEXT, created_at TEXT NOT NULL);
CREATE INDEX idx_tt_article ON translation_tasks(article_id,target_locale); CREATE INDEX idx_tt_status ON translation_tasks(status,created_at DESC);
CREATE TABLE render_units (unit_key TEXT PRIMARY KEY, kind TEXT NOT NULL, locale TEXT NOT NULL, output_path TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER DEFAULT 0, last_error TEXT, duration_ms INTEGER, rendered_at TEXT, updated_at TEXT NOT NULL);
CREATE INDEX idx_ru_status ON render_units(status,updated_at);
CREATE TABLE scheduled_publish (article_id TEXT PRIMARY KEY, locale TEXT NOT NULL, publish_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'scheduled', created_at TEXT NOT NULL); CREATE INDEX idx_sp_due ON scheduled_publish(status,publish_at);
CREATE TABLE login_attempts (id INTEGER PRIMARY KEY AUTOINCREMENT, identifier TEXT NOT NULL, ip TEXT NOT NULL, success INTEGER NOT NULL, user_agent TEXT, created_at TEXT NOT NULL); CREATE INDEX idx_la_lookup ON login_attempts(identifier,created_at DESC);
CREATE TABLE audit_log (id INTEGER PRIMARY KEY AUTOINCREMENT, actor TEXT NOT NULL, action TEXT NOT NULL, target_type TEXT, target_id TEXT, detail TEXT, ip TEXT, created_at TEXT NOT NULL); CREATE INDEX idx_audit_time ON audit_log(created_at DESC); CREATE INDEX idx_audit_target ON audit_log(target_type,target_id);
CREATE TABLE system_log (id INTEGER PRIMARY KEY AUTOINCREMENT, level TEXT NOT NULL, component TEXT NOT NULL, message TEXT NOT NULL, detail TEXT, created_at TEXT NOT NULL); CREATE INDEX idx_syslog_time ON system_log(created_at DESC);
